Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='watchersexit', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='A watcher waits for an end marker or for its process to end, and then exits', body='Poll for the end marker in a loop that exits. Never follow a log with tail and a pipe, because the reader outlives the run. A watcher also waits for the process to end, not only for a success line. A step in a script with pipefail never ends in a filtering grep.', rationale='A lingering watcher fires stale events, and a watcher that waits for a line that cannot come stalls for hours.', supersedes=()))